import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
// detail pre kind
await pg.goto('http://127.0.0.1:8099/#/pages/detail/index?id=FX-20260718-0045&kind=pre',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(2500)
const info=await pg.evaluate(()=>{
  const grid=document.querySelector('.photo-grid')
  const cols=grid?getComputedStyle(grid).gridTemplateColumns:null
  return { className: grid?grid.className:null, columns: cols, ncols: cols?cols.split(' ').length:null }
})
console.log(JSON.stringify(info,null,2))
// scroll to 现场自救 area
await pg.evaluate(()=>{const h=[...document.querySelectorAll('h3')].find(e=>/现场自救/.test(e.textContent)); if(h) h.scrollIntoView({block:'center'})})
await pg.waitForTimeout(400)
await pg.screenshot({path:'D:/repository/_pg.png'})
await b.close()

